from rest_framework.throttling import SimpleRateThrottle
from DaventProject.throttling import _ResilientThrottleMixin

class FeedWriteThrottle(_ResilientThrottleMixin, SimpleRateThrottle):
    #Escrituras de comprador (comentar/likear/votar): bucket por cuenta —
    #AnonRateThrottle saltaría la cuota porque Customer.is_authenticated=True.
    scope   =   'store_review'
    def get_cache_key(self, request, view):
        customer    =   getattr(request, 'customer', None)
        ident       =   f'c{customer.pk}' if customer is not None else self.get_ident(request)
        return self.cache_format % {'scope': self.scope, 'ident': ident}

class ChatSendThrottle(_ResilientThrottleMixin, SimpleRateThrottle):
    #ScopedRateThrottle lee view.throttle_scope (ausente en todo el repo)
    #-> allow_request siempre True. Bucket por usuario con rate propio.
    scope   =   'chat_send'
    def get_cache_key(self, request, view):
        return self.cache_format % {'scope': self.scope, 'ident': request.user.pk}

